fn greater_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // We assume `a` and `b` have the same length.
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");

    // Zip the two vectors and compare element-wise, collecting the results into a Vec<bool>.
    a.iter()
     .zip(b.iter())
     .map(|(&x, &y)| x >= y)
     .collect()
}

